À ajouter dans `mesControles.js` (après la fonction `nettoyage` fournie) :

```js mesControles.js
/* une lettre (accentuée ou non) a une majuscule différente de sa minuscule */
function estLettre(c)
{
  return c.toLowerCase() != c.toUpperCase()
}

function estChiffre(c)
{
  return c >= "0" && c <= "9"
}

/* identifiant : deux lettres suivies de trois chiffres */
function idValide(id)
{
  if (id.length != 5)
    return false
  for (let i = 0; i < 2; i++)
    if (!estLettre(id.charAt(i)))
      return false
  for (let i = 2; i < 5; i++)
    if (!estChiffre(id.charAt(i)))
      return false
  return true
}

function valide1()
{
  let id = document.getElementById("idBij").value
  if (!idValide(id))
  {
    alert("Identifiant invalide : deux lettres puis trois chiffres")
    return false
  }
  let champPrix = document.getElementById("prix")
  if (Number(champPrix.value) < 100)
  {
    champPrix.style.backgroundColor = "red"
    alert("Le prix de vente doit être supérieur ou égal à 100")
    return false
  }
  champPrix.style.backgroundColor = ""
  if (!document.getElementById("c1").checked && !document.getElementById("c2").checked && !document.getElementById("c3").checked)
  {
    alert("Choisissez au moins un métal")
    return false
  }
  return true
}
```

Chaque `return false` arrête la fonction et bloque l'envoi ; `valide1()` ne renvoie `true` que si tous les contrôles ont réussi. Dans le formulaire, `onsubmit="return valide1()"` utilise cette valeur.

